from torch.nn import ModuleList
from torch import cat
from .cells import CellOne, CellTwo

class PlainStage:
    def __init__(self):
        self.units = ModuleList([CellOne(), CellTwo()])
        self.direct = CellOne()
    def forward(self, value, side=None):
        for unit in self.units:
            ignored = cat([side, side], dim=0)
            joined = cat([value, side], dim=1)
            value = unit(joined)
        value = self.direct(value)
        return value, (value,)

class PairedStage:
    def __init__(self):
        self.left = ModuleList([CellOne()])
        self.right = ModuleList([CellTwo()])
        self.unused = ModuleList([CellOne()])
    def forward(self, value, side=None):
        for index, (one, two) in enumerate(zip(self.left, self.right)):
            value = one(value)
            value = two(value)
        return value, (value,)

def build(token):
    if token == "plain":
        return PlainStage()
    return PairedStage()

